    due = pdate(b.get('lastPayDate'))
    cut_next = pdate(b.get('nextStatementDate'))
    tl = b.get('debtTL') if isinstance(b.get('debtTL'), dict) else dict()
    parts = []
    if not pdate(b.get('statementDate')):
        text = L['no_statement_yet'].replace('{last4}', last4).replace('{name}', name_sp)
        nodebt = True
    else:
        owing, clear = [], []
        for i, (key, cname, sub, unit) in enumerate(CUR):
            blk = b.get(key)
            if not isinstance(blk, dict) or not blk:
                continue
            (owing if num(blk.get('remainingDebt')) > 0 else clear).append(i)
        nodebt = str(b.get('statementPaymentStatus')) == 'NO_DEBT' or not owing
        if nodebt:
            text = (L['no_statement_debt'].replace('{last4}', last4).replace('{name}', name_sp)
                    .replace('{date}', say_date(b.get('statementDate'))).replace('{x}', money(tl.get('totalDebt'), 0))
                    .replace('{due}', say_date(b.get('lastPayDate'))))
        else:
            intro = (L['intro'].replace('{last4}', last4).replace('{name}', name_sp)
                     .replace('{date}', say_date(b.get('statementDate'))))
            for i in owing:
                blk = b.get(CUR[i][0])
                x, z = money(blk.get('statementDebt'), i), money(blk.get('minPayment'), i)
                y, t = money(blk.get('remainingDebt'), i), money(blk.get('remainingMinPayment'), i)
                if i == 0:
                    rmp, mp = num(blk.get('remainingMinPayment')), num(blk.get('minPayment'))
                    if rmp <= 0:
                        line = L['tl_min_paid']
                    elif rmp >= mp:
                        line = L['tl_none_paid']
                    else:
                        line = L['tl_below_min']
                else:
                    line = L['foreign'].replace('{cur}', CUR[i][1])
                line = line.replace('{x}', x).replace('{y}', y).replace('{z}', z).replace('{t}', t)
                parts.append(line)
            parts[0] = intro + parts[0]
            if clear:
                names = [CUR[i][1] for i in clear]
                lst = names[0] if len(names) == 1 else ', '.join(names[:-1]) + ' ve ' + names[-1]
                parts.append(L['no_debt_in'].replace('{list}', lst))
            passed = bool(td and due and td > due)
            if passed and str(b.get('automaticPaymentFlag')) == 'Y' and num(tl.get('remainAutomaticPaymentAmount')) > 0:
                parts.append(L['auto_pay'].replace('{x}', money(tl.get('remainAutomaticPaymentAmount'), 0)))
