DECIDE_AFTER = COMMON + r'''
vars['route'] = ''
if not ok('decide'):
    close('close_week_error')
else:
    d = load('dec', 'decide_response.data.')
    vars['new_cut'] = say_date(d.get('statementDate'))
    vars['new_due'] = say_date(d.get('statementDueDate'))
