'''

CHANGE_AFTER = COMMON + r'''
d = load('chg', 'change_response.data.')
if ok('change') and str(d.get('exitState')) == 'OK' and str(d.get('responseCode')) in ('0', '0.0'):
    name = vars.get('card_name') or ''
    vars['week_done_line'] = (L['week_done'].replace('{last4}', digits_say(vars.get('card_last4')))
