# The state tool: the model reports what the caller said; the code picks the next line or route.
SAID = COMMON + r'''
kind = str(params.get('kind') or 'other')
text = str(params.get('words') or '')
digits = str(params.get('digits') or '')
week = int(num(params.get('week')))
also = str(params.get('also') or '')
step = vars.get('step') or 'card'
vars['route'] = ''
if also in ('email', 'week') and vars.get('has_read') != 'yes':
    vars['also'] = also
if kind == 'silence':
    s = int(num(vars.get('silence'))) + 1
    vars['silence'] = s
    if s >= %(max_silence)d:
        close('close_silence')
    else:
        say(vars.get('ask_now') or '')
else:
    vars['silence'] = 0
if kind == 'silence':
    pass
elif kind == 'repeat':
